with gaps as (select *, case when lag(started_at) over (partition by device order by started_at, id) is null or started_at > lag(started_at) over (partition by device order by started_at, id) + interval '90' day then 1 else 0 end as new_group_flag from sessions), islands as (select *, sum(new_group_flag) over (partition by device order by started_at, id rows between unbounded preceding and current row) as island_id from gaps) select id, browser, started_at, country, island_id, case when country rlike '^(SG|TH)$' then 'CORE' when country rlike '^(US|JP)$' then 'EXTENDED' else 'OTHER_ZONE' end as country_zone from islands order by id desc nulls first
